/* ---------- Escala semanal ---------- */
const ES_TIPO = { trabalho: 'Trabalho', plantao: 'Extra (abre–fecha)', folga: 'Folga', ferias: 'Férias', atestado: 'Atestado' };
const ES_COR = { trabalho: ['#FFFFFF', '#141414'], plantao: ['#FFFFFF', '#141414'], folga: ['#F2F2F2', '#4A4A4A'], ferias: ['#E8ECF4', '#3A4A6A'], atestado: ['#FBE3E6', '#8F1F2C'] };
const ES_TURNO = {
  'LZ|Dia': ['#FFE4E4', '#FF5C5C', '#8F1F1F'], 'LZ|Intermédio': ['#FFC9C9', '#E04848', '#6E1414'], 'LZ|Noite': ['#FFB3B3', '#D93A3A', '#6E1414'],
  'VM|Dia': ['#FDEED3', '#F2A22C', '#6E4300'], 'VM|Intermédio': ['#F2A22C', '#B86E00', '#141414'], 'VM|Noite': ['#F8CB7C', '#B86E00', '#4A2E00'],
  'Extra': ['#FFFFFF', '#141414', '#141414']
};
const esKey = x => x.op ? 'o' + x.op : 'a:' + String(x.nome || '').trim().toLowerCase();
const esSig = x => x ? [x.tipo, x.patio || '', x.ent || '', x.sai || '', x.ii || '', x.fi || ''].join('|') : '';
const esDias = sem => [0, 1, 2, 3, 4, 5, 6].map(i => addDias(sem, i));
const ES_DIA = ['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'];
const esM = t => { if (!t || !/^\d{1,2}:\d{2}/.test(t)) return null; const [h, m] = t.split(':').map(Number); return h * 60 + m + (h < 6 ? 1440 : 0); };
const esHH = m => m == null ? '—' : `${String(Math.floor((m % 1440) / 60)).padStart(2, '0')}h${String(m % 60).padStart(2, '0')}`;
const esT = t => t ? esHH(esM(t)) : '—';
const esTrab = x => x && (x.tipo === 'trabalho' || x.tipo === 'plantao') && x.ent && x.sai;
const esIntOk = x => { const e = esM(x.ent), s = esM(x.sai), i = esM(x.ii), f = esM(x.fi); return i != null && f != null && i >= e && f <= s && f > i; };
const esMin = x => { if (!esTrab(x)) return 0; let m = esM(x.sai) - esM(x.ent); if (esIntOk(x)) m -= esM(x.fi) - esM(x.ii); return Math.max(0, m); };
const esHoras = m => `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}`;
const esSigla = (pid, pats) => /luz/i.test(((pats || []).find(p => p.id === pid) || {}).nome || '') ? 'LZ' : 'VM';
function esTurno(x, pats) {
  if (!x) return null;
  if (!esTrab(x)) { const [bg, fg] = ES_COR[x.tipo] || ES_COR.folga; return { curto: ES_TIPO[x.tipo] || '—', longo: ES_TIPO[x.tipo] || '—', sig: '—', bg, bd: '#BDBDBD', fg, trab: false }; }
  const pn = ((pats || []).find(p => p.id === x.patio) || {}).nome || '', sg = esSigla(x.patio, pats);
  if (x.tipo === 'plantao') { const c = ES_TURNO.Extra; return { curto: `${sg} · Abre–fecha`, longo: `${pn} · Extra (abre–fecha)`, sig: sg, bg: c[0], bd: c[1], fg: c[2], trab: true, extra: true }; }
  const e = esM(x.ent), per = e < 12 * 60 ? 'Dia' : e < 15 * 60 ? 'Intermédio' : 'Noite', c = ES_TURNO[sg + '|' + per];
  return { curto: `${sg} · ${per}`, longo: `${pn} · ${per}`, sig: sg, bg: c[0], bd: c[1], fg: c[2], trab: true };
}
const esChip = tu => tu ? `<span class="eschip" style="background:${tu.bg};color:${tu.fg};box-shadow:inset 4px 0 0 ${tu.bd}${tu.extra ? ';outline:1.5px dashed #141414' : ''}">${esc(tu.longo)}</span>` : '';
function esPessoas(E, itens) {
  const m = new Map(); (E.pessoas || []).forEach(p => m.set('o' + p.op, { k: 'o' + p.op, op: p.op, nome: p.nome }));
  (itens || []).forEach(x => { const k = esKey(x); if (!m.has(k)) m.set(k, { k, op: x.op || null, nome: x.nome }); });
  (S.esAvulsos || []).forEach(n => { const k = 'a:' + n.toLowerCase(); if (!m.has(k)) m.set(k, { k, op: null, nome: n }); });
  return [...m.values()].sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));
}
// mesma regra do servidor: o pátio nunca fica sem ninguém; Extra (abre–fecha) sozinho é exceção registrada
function esValidar(itens, pats) {
  const bl = [], ex = [], PN = id => ((pats || []).find(p => p.id === id) || {}).nome || 'pátio';
  const lb = d => `${ES_DIA[(new Date(d + 'T12:00:00Z').getUTCDay() + 6) % 7].slice(0, 3)} ${ddmm(d)}`;
  const L = (itens || []).filter(esTrab);
  L.forEach(x => {
    const e = esM(x.ent), s = esM(x.sai);
    if (s <= e) bl.push(`${lb(x.dia)}: saída de ${x.nome} antes da entrada`);
    if (x.tipo === 'trabalho' && !x.ii) bl.push(`${lb(x.dia)}: falta o intervalo de ${x.nome}`);
    else if (x.ii && !esIntOk(x)) bl.push(`${lb(x.dia)}: intervalo de ${x.nome} (${x.ii}–${x.fi || '?'}) fora do horário de trabalho`);
  });
  const grupos = {}; L.filter(x => x.patio).forEach(x => (grupos[x.dia + '|' + x.patio] = grupos[x.dia + '|' + x.patio] || []).push(x));
  Object.keys(grupos).sort().forEach(g => {
    const G = grupos[g], [d, p] = g.split('|'), e0 = Math.min(...G.map(x => esM(x.ent))), s1 = Math.max(...G.map(x => esM(x.sai)));
    let ini = null;
    for (let t = e0; t <= s1; t++) {
      const n = t < s1 ? G.filter(x => esM(x.ent) <= t && t < esM(x.sai) && !(esIntOk(x) && esM(x.ii) <= t && t < esM(x.fi))).length : 1;
      if (n === 0 && ini == null) ini = t;
      if (n > 0 && ini != null) { bl.push(`${lb(d)} · ${PN(+p)}: pátio sem ninguém das ${esHH(ini)} às ${esHH(t)}`); ini = null; }
    }
    if (G.length === 1 && G[0].tipo === 'plantao') ex.push(`${lb(d)} · ${PN(+p)}: ${G[0].nome} sozinho(a) como Extra (abre–fecha). Exceção registrada.`);
  });
  return { bloqueios: bl, excecoes: ex };
}
// barra de cobertura do dia por pátio (07h às 02h)
function esCobertura(itens, d, pats) {
  const A = 7 * 60, B = 26 * 60, W = B - A;
  return (pats || []).map(p => {
    const G = (itens || []).filter(x => x.dia === d && x.patio === p.id && esTrab(x));
    if (!G.length) return '';
    const e0 = Math.min(...G.map(x => esM(x.ent))), s1 = Math.max(...G.map(x => esM(x.sai))), seg = [];
    for (let t = e0; t < s1; t++) {
      const n = Math.min(2, G.filter(x => esM(x.ent) <= t && t < esM(x.sai) && !(esIntOk(x) && esM(x.ii) <= t && t < esM(x.fi))).length);
      const u = seg[seg.length - 1]; if (u && u.n === n) u.b = t + 1; else seg.push({ a: t, b: t + 1, n });
    }
    const cor = ['#FF5C5C', '#F2A22C', '#141414'];
    return `<div class="escob"><div class="row between"><b>${esc(p.nome)}</b><span class="tiny muted">${G.length} na escala</span></div>
      <div class="escob-bar">${seg.map(s => `<span style="left:${((s.a - A) / W * 100).toFixed(2)}%;width:${((s.b - s.a) / W * 100).toFixed(2)}%;background:${cor[s.n]}" title="${esHH(s.a)}–${esHH(s.b)}: ${['ninguém', '1 pessoa', '2 ou mais'][s.n]}"></span>`).join('')}</div>
      <div class="escob-esc"><span>07h</span><span>11h</span><span>15h</span><span>19h</span><span>23h</span><span>02h</span></div></div>`;
  }).join('') + `<div class="legend"><span>${dot('#141414')} 2 ou mais</span><span>${dot('#F2A22C')} 1 pessoa</span><span>${dot('#FF5C5C')} ninguém</span></div>`;
}
function esPainelValid(V) {
  return `${V.bloqueios.length ? `<div class="esbloq"><b style="color:#8F1F1F">${V.bloqueios.length} bloqueio(s): a escala não pode ser publicada</b><ul style="margin:6px 0 0;padding-left:18px">${V.bloqueios.map(b => `<li>${esc(b)}</li>`).join('')}</ul><div class="tiny muted">Regra: o pátio precisa ter sempre alguém, inclusive no intervalo de cada manobrista.</div></div>` : '<div class="msg ok" style="margin-top:12px">✓ Sem bloqueios: o pátio tem sempre alguém.</div>'}
    ${V.excecoes.length ? `<div class="esexc"><b>Exceções registradas</b>${V.excecoes.map(t => `<div>${esc(t)}</div>`).join('')}</div>` : ''}`;
}
// folha geral (tela do editor): pessoas × dias, no visual Las Vagas
function folhaEscala(E, itens, ant, opts) {
  opts = opts || {};
  const dias = esDias(E.semana), pats = E.patios || [];
  const by = {}; (itens || []).forEach(x => by[esKey(x) + '|' + x.dia] = x);
  const antBy = {}; (ant || []).forEach(x => antBy[esKey(x) + '|' + x.dia] = x);
