    const x = by[p.k + '|' + d], ch = mud.has(p.k + '|' + d), tu = esTurno(x, pats);
    if (!x) return `<td class="esfc vaz${ch ? ' alt' : ''}">${ch ? '<small>removido</small>' : '—'}</td>`;
    return `<td class="esfc${ch ? ' alt' : ''}" style="background:${tu.bg};color:${tu.fg};box-shadow:inset 4px 0 0 ${tu.bd}${tu.extra ? ';outline:1.5px dashed #141414;outline-offset:-3px' : ''}">
      <b>${esc(tu.curto)}</b>${tu.trab ? `<div>${esT(x.ent)} – ${esT(x.sai)}</div>${esIntOk(x) ? `<small>Int. ${esT(x.ii)} – ${esT(x.fi)}</small>` : ''}` : ''}${ch ? '<small class="altt">ALTERADO</small>' : ''}</td>`;
  };
  const ver = opts.versao ? `versão ${opts.versao}${opts.publicada_em ? ' · publicada em ' + dt(opts.publicada_em) : ''}` : 'rascunho · não publicado';
